package com.vinhho.onthi10ai.data.solver

import com.vinhho.onthi10ai.data.solver.OfflineQuizBank.RawQuestion

internal object OfflineQuizBankLiterature {

    fun buildForGrade(grade: Int): List<RawQuestion> = when (grade) {
        in 1..5 -> primaryQuestions(grade)
        in 6..9 -> secondaryQuestions(grade)
        else -> highSchoolQuestions(grade)
    }

    private fun primaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[Tiếng Việt Lớp $g]"
        return listOf(
            RawQuestion("$tag Trong câu 'Ông mặt trời thức dậy sau lũy tre', biện pháp nghệ thuật nào được dùng?", listOf("Nhân hóa", "So sánh", "Điệp ngữ", "Nói quá"), 0, "Gọi mặt trời là 'ông' và tả hành động 'thức dậy' là phép nhân hóa."),
            RawQuestion("$tag Từ nào sau đây viết đúng chính tả?", listOf("xinh xắn", "sinh xắn", "xinh sắn", "sinh sắn"), 0, "Từ láy miêu tả vẻ đẹp dễ thương viết đúng là 'xinh xắn'."),
            RawQuestion("$tag Từ đồng nghĩa với 'siêng năng' là:", listOf("chăm chỉ", "lười biếng", "nhút nhát", "vội vàng"), 0, "'Chăm chỉ' và 'siêng năng' đều chỉ đức tính cần cù, chịu khó."),
            RawQuestion("$tag Câu 'Mặt hồ phẳng lặng như một tấm gương soi' sử dụng biện pháp tu từ nào?", listOf("So sánh", "Nhân hóa", "Hoán dụ", "Đảo ngữ"), 0, "Dùng từ so sánh 'như' đối chiếu mặt hồ với tấm gương."),
            RawQuestion("$tag Trong câu 'Đàn chim sẻ ríu rít trên cành bàng', bộ phận chủ ngữ là:", listOf("Đàn chim sẻ", "ríu rít", "trên cành bàng", "cành bàng"), 0, "Chủ ngữ trả lời câu hỏi 'Con gì?': Đàn chim sẻ."),
            RawQuestion("$tag Từ nào trái nghĩa với 'dũng cảm'?", listOf("hèn nhát", "gan dạ", "anh hùng", "kiên cường"), 0, "'Hèn nhát' trái nghĩa với 'dũng cảm'."),
            RawQuestion("$tag Trong các từ sau, từ nào là từ láy?", listOf("long lanh", "sách vở", "bàn ghế", "quần áo"), 0, "'Long lanh' là từ láy âm đầu 'l'; các từ còn lại là từ ghép."),
            RawQuestion("$tag Dấu câu nào dùng để kết thúc câu hỏi?", listOf("Dấu chấm hỏi (?)", "Dấu chấm (.)", "Dấu phẩy (,)", "Dấu chấm phẩy (;)"), 0, "Cuối câu nghi vấn (câu hỏi) đặt dấu chấm hỏi (?)."),
            RawQuestion("$tag Thành ngữ 'Chịu thương chịu khó' ca ngợi phẩm chất gì?", listOf("Cần cù, nhẫn nại vượt khó", "Kiêu ngạo, tự phụ", "Nóng nảy, hấp tấp", "Lười biếng, ỷ lại"), 0, "Thành ngữ nói về người lao động chăm chỉ, bền bỉ."),
            RawQuestion("$tag Từ 'hoa hồng' thuộc từ loại nào?", listOf("Danh từ", "Động từ", "Tính từ", "Đại từ"), 0, "'Hoa hồng' là danh từ chỉ sự vật."),
            RawQuestion("$tag Trong bài văn tả cảnh, phần nào giới thiệu đối tượng được miêu tả?", listOf("Mở bài", "Thân bài", "Kết bài", "Chú thích"), 0, "Mở bài giới thiệu cảnh vật và ấn tượng ban đầu."),
            RawQuestion("$tag Từ nào viết đúng chính tả với vần tr/ch?", listOf("trung thực", "chung thực", "chong sáng", "trăm chỉ"), 0, "'Trung thực' là từ đúng chính tả."),
            RawQuestion("$tag Câu 'Hôm nay trời đẹp quá!' thuộc kiểu câu gì?", listOf("Câu cảm", "Câu kể", "Câu hỏi", "Câu khiến"), 0, "Câu có từ cảm thán 'quá' và dấu chấm than (!) bộc lộ cảm xúc."),
            RawQuestion("$tag Từ 'chạy nhảy' thuộc từ loại nào?", listOf("Động từ", "Danh từ", "Tính từ", "Quan hệ từ"), 0, "'Chạy nhảy' chỉ hoạt động của con người, động vật nên là động từ."),
            RawQuestion("$tag Cặp quan hệ từ 'Vì ... nên ...' biểu thị quan hệ gì giữa hai vế câu ghép?", listOf("Nguyên nhân - kết quả", "Tương phản", "Điều kiện - kết quả", "Tăng tiến"), 0, "'Vì ... nên ...' nối hai vế câu có quan hệ nguyên nhân - kết quả."),
            RawQuestion("$tag Tác giả của truyện cổ tích 'Tấm Cám' là ai?", listOf("Sáng tác dân gian", "Nguyễn Du", "Tô Hoài", "Nam Cao"), 0, "Truyện cổ tích do nhân dân sáng tác và lưu truyền qua nhiều thế hệ."),
            RawQuestion("$tag Biện pháp tu từ nào lặp lại một từ hoặc cụm từ để nhấn mạnh ý?", listOf("Điệp ngữ", "So sánh", "Nói giảm", "Chơi chữ"), 0, "Điệp ngữ là nhắc lại từ ngữ nhiều lần để tăng sức biểu cảm."),
            RawQuestion("$tag Trong câu 'Ngoài vườn, hoa cúc nở vàng rực', trạng ngữ là:", listOf("Ngoài vườn", "hoa cúc", "nở vàng rực", "vàng rực"), 0, "'Ngoài vườn' là trạng ngữ chỉ nơi chốn."),
            RawQuestion("$tag Từ nào đồng nghĩa với 'Tổ quốc'?", listOf("Đất nước", "Thành phố", "Làng quê", "Gia đình"), 0, "'Đất nước', 'giang sơn', 'non sông' đồng nghĩa với 'Tổ quốc'."),
            RawQuestion("$tag Từ 'xanh biếc' thuộc từ loại nào?", listOf("Tính từ", "Danh từ", "Động từ", "Số từ"), 0, "'Xanh biếc' chỉ màu sắc, tính chất của sự vật nên là tính từ."),
            RawQuestion("$tag Câu tục ngữ 'Đi một ngày đàng, học một sàng khôn' khuyên chúng ta điều gì?", listOf("Chịu khó đi nhiều, học hỏi mở rộng hiểu biết", "Chỉ nên ở trong nhà", "Không cần đọc sách", "Ngủ nhiều để khỏe mạnh"), 0, "Khuyên con người ham học hỏi từ thực tế cuộc sống rộng lớn."),
            RawQuestion("$tag Tên riêng địa lí Việt Nam 'Thừa Thiên Huế' cần viết hoa như thế nào?", listOf("Viết hoa chữ cái đầu mỗi tiếng", "Chỉ viết hoa chữ cái đầu tiên", "Viết thường toàn bộ", "Chỉ viết hoa chữ 'Huế'"), 0, "Tên địa lí Việt Nam viết hoa chữ cái đầu của tất cả các tiếng tạo thành tên riêng."),
            RawQuestion("$tag Tác phẩm 'Dế Mèn phiêu lưu ký' là của nhà văn nào?", listOf("Tô Hoài", "Nguyễn Nhật Ánh", "Võ Quảng", "Trần Đăng Khoa"), 0, "Nhà văn Tô Hoài sáng tác 'Dế Mèn phiêu lưu ký' năm 1941."),
            RawQuestion("$tag Câu 'Cháu hãy giúp bà xâu kim nhé!' thuộc kiểu câu gì?", listOf("Câu khiến", "Câu hỏi", "Câu kể", "Câu cảm"), 0, "Câu có 'hãy', 'nhé' dùng để nhờ vả, đề nghị là câu cầu khiến."),
            RawQuestion("$tag Tiếng 'học' gồm những bộ phận nào?", listOf("Âm đầu h, vần oc, thanh nặng", "Âm đầu ho, vần c, thanh nặng", "Vần học, không âm đầu", "Âm đầu h, vần o, thanh sắc"), 0, "Cấu tạo tiếng gồm âm đầu 'h', vần 'oc' và thanh nặng."),
            RawQuestion("$tag Từ nào trái nghĩa với 'khổng lồ'?", listOf("tí hon", "to lớn", "vĩ đại", "cao ngất"), 0, "'Tí hon' chỉ kích thước rất nhỏ, trái nghĩa với 'khổng lồ'."),
            RawQuestion("$tag Thành ngữ 'Uống nước nhớ nguồn' nhắc nhở điều gì?", listOf("Lòng biết ơn những người đi trước", "Tiết kiệm nguồn nước sạch", "Cách giữ gìn sức khỏe", "Kỹ năng bơi lội"), 0, "Nhắc nhở đạo lí biết ơn ông bà, cha mẹ, tổ tiên và các thế hệ đi trước."),
            RawQuestion("$tag Trong câu ghép 'Tuy nhà xa nhưng bạn Nam luôn đi học đúng giờ', cặp quan hệ từ biểu thị ý gì?", listOf("Tương phản", "Nguyên nhân", "Giả thiết", "Lựa chọn"), 0, "'Tuy ... nhưng ...' biểu thị mối quan hệ tương phản (đối lập)."),
            RawQuestion("$tag Dấu hai chấm (:) trước lời nói trực tiếp của nhân vật thường kết hợp với dấu gì?", listOf("Dấu ngoặc kép hoặc dấu gạch đầu dòng", "Dấu chấm hỏi", "Dấu chấm lửng", "Dấu ngoặc đơn"), 0, "Báo hiệu lời dẫn trực tiếp bằng dấu ngoặc kép hoặc xuống dòng gạch đầu dòng."),
            RawQuestion("$tag Câu tục ngữ 'Có công mài sắt, có ngày nên kim' đề cao đức tính nào?", listOf("Kiên trì, nhẫn nại", "Thông minh bẩm sinh", "Khéo tay hay làm", "Tiết kiệm tiền bạc"), 0, "Khuyên người học biết kiên nhẫn rèn luyện sẽ đạt thành công."),
            RawQuestion("$tag Từ 'nhà cửa' là loại từ ghép gì?", listOf("Từ ghép tổng hợp", "Từ ghép phân loại", "Từ láy hoàn toàn", "Từ đơn"), 0, "'Nhà cửa' chỉ chung nơi ăn chốn ở, không phân loại cụ thể nên là từ ghép tổng hợp."),
            RawQuestion("$tag Từ nào viết đúng chính tả với s/x?", listOf("chia sẻ", "chia xẻ", "xâu sắc", "sử lý"), 0, "'Chia sẻ' (sẻ chia) viết đúng là 's'."),
            RawQuestion("$tag Trong câu 'Những bông hoa phượng nở đỏ rực sân trường', vị ngữ là:", listOf("nở đỏ rực sân trường", "Những bông hoa phượng", "bông hoa phượng", "sân trường"), 0, "Vị ngữ nêu hoạt động/trạng thái của chủ ngữ: 'nở đỏ rực sân trường'."),
            RawQuestion("$tag Hai câu thơ 'Tre xanh, xanh tự bao giờ / Chuyện ngày xưa đã có bờ tre xanh' trích trong bài thơ nào?", listOf("Tre Việt Nam", "Hạt gạo làng ta", "Bầm ơi", "Lượm"), 0, "Trích bài thơ 'Tre Việt Nam' của nhà thơ Nguyễn Duy."),
            RawQuestion("$tag Để liên kết các câu bằng phép thế, ta thay thế từ ngữ ở câu trước bằng:", listOf("Đại từ hoặc từ ngữ đồng nghĩa", "Dấu chấm than", "Các số thứ tự", "Từ trái nghĩa"), 0, "Phép thế dùng đại từ (nó, họ, ấy...) hoặc từ đồng nghĩa tránh lặp từ."),
            RawQuestion("$tag Từ nào sau đây là từ láy vần?", listOf("lác đác", "xinh xắn", "đo đỏ", "lung linh"), 0, "'Lác đác' lặp lại phần vần 'ác' nên là từ láy vần."),
            RawQuestion("$tag Câu 'Mùa xuân, cây cối đâm chồi nảy lộc' có trạng ngữ chỉ gì?", listOf("Thời gian", "Nơi chốn", "Nguyên nhân", "Mục đích"), 0, "'Mùa xuân' xác định thời gian diễn ra sự việc."),
            RawQuestion("$tag Tác giả của bài thơ 'Hạt gạo làng ta' là ai?", listOf("Trần Đăng Khoa", "Xuân Quỳnh", "Huy Cận", "Tố Hữu"), 0, "Nhà thơ Trần Đăng Khoa sáng tác 'Hạt gạo làng ta' năm 1968."),
            RawQuestion("$tag Trong một lá thư, phần cuối thư cần ghi nội dung gì?", listOf("Lời chúc, lời chào và chữ ký", "Địa chỉ bưu điện", "Tóm tắt nội dung sách", "Đáp án bài tập"), 0, "Cuối thư luôn có lời chúc/chào và chữ ký của người viết."),
            RawQuestion("$tag Từ nào đồng nghĩa với 'bảo vệ'?", listOf("gìn giữ", "phá hoại", "vứt bỏ", "lãng quên"), 0, "'Gìn giữ' đồng nghĩa với 'bảo vệ'."),
            RawQuestion("$tag Dấu phẩy trong câu 'Lan, Mai, Hùng đều đạt học sinh giỏi' có tác dụng gì?", listOf("Ngăn cách các bộ phận cùng giữ chức vụ chủ ngữ", "Kết thúc câu", "Báo hiệu lời nói trực tiếp", "Đánh dấu câu hỏi"), 0, "Dấu phẩy ngăn cách các từ ngữ đồng chức vụ liệt kê trong câu."),
            RawQuestion("$tag Chọn từ viết đúng chính tả về thanh hỏi / ngã:", listOf("nghĩ ngợi", "nghỉ ngợi", "dủng cảm", "mủm mĩm"), 0, "'Nghĩ ngợi' (suy nghĩ) dùng thanh ngã; 'nghỉ ngơi' mới dùng thanh hỏi.")
        )
    }

    private fun secondaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[Ngữ văn Lớp $g]"
        return listOf(
            RawQuestion("$tag Tác giả của bài thơ 'Sang thu' là nhà thơ nào?", listOf("Hữu Thỉnh", "Viễn Phương", "Thanh Hải", "Chính Hữu"), 0, "Nhà thơ Hữu Thỉnh sáng tác bài thơ 'Sang thu' vào cuối năm 1977."),
            RawQuestion("$tag Hình ảnh 'mặt trời trong lăng rất đỏ' trong 'Viếng lăng Bác' sử dụng biện pháp tu từ nào?", listOf("Ẩn dụ", "So sánh", "Hoán dụ", "Nói quá"), 0, "'Mặt trời trong lăng' ẩn dụ cho Bác Hồ kính yêu."),
            RawQuestion("$tag Nhân vật ông Hai trong truyện ngắn 'Làng' của Kim Lân tiêu biểu cho tình cảm gì?", listOf("Tình yêu làng gắn liền với lòng yêu nước", "Khát vọng làm giàu", "Tình bạn học trò", "Niềm đam mê hội họa"), 0, "Ông Hai yêu làng Chợ Dầu nhưng sẵn sàng đặt lòng yêu nước lên trên hết."),
            RawQuestion("$tag Tác phẩm 'Truyện Kiều' của Nguyễn Du viết theo thể thơ nào?", listOf("Lục bát", "Thất ngôn bát cú", "Thơ tự do", "Song thất lục bát"), 0, "Truyện Kiều gồm 3.254 câu thơ lục bát."),
            RawQuestion("$tag Văn bản 'Tức nước vỡ bờ' trích từ tiểu thuyết nào của Ngô Tất Tố?", listOf("Tắt đèn", "Bước đường cùng", "Số đỏ", "Lão Hạc"), 0, "'Tức nước vỡ bờ' là đoạn trích đặc sắc trong tiểu thuyết 'Tắt đèn'."),
            RawQuestion("$tag Tác phẩm 'Lão Hạc' của Nam Cao được viết theo phương thức biểu đạt chính nào?", listOf("Tự sự", "Biểu cảm", "Thuyết minh", "Nghị luận"), 0, "Truyện ngắn sử dụng phương thức tự sự là chính, kết hợp miêu tả và biểu cảm."),
            RawQuestion("$tag Trong câu thơ 'Áo chàm đưa buổi phân li / Cầm tay nhau biết nói gì hôm nay', hình ảnh 'áo chàm' dùng phép tu từ nào?", listOf("Hoán dụ", "So sánh", "Nói quá", "Chơi chữ"), 0, "'Áo chàm' lấy dấu hiệu trang phục để chỉ đồng bào Việt Bắc (hoán dụ)."),
            RawQuestion("$tag Bài thơ 'Mùa xuân nho nhỏ' của Thanh Hải được viết bằng thể thơ nào?", listOf("Thơ năm chữ", "Thơ lục bát", "Thơ tự do", "Thơ bảy chữ"), 0, "'Mùa xuân nho nhỏ' gồm 6 khổ thơ năm chữ giàu nhạc điệu."),
            RawQuestion("$tag Câu thơ 'Bác đã đi rồi sao, Bác ơi!' của Tố Hữu sử dụng kiểu câu nào xét theo mục đích nói?", listOf("Câu cảm thán", "Câu trần thuật", "Câu cầu khiến", "Câu nghi vấn dùng để hỏi thông tin"), 0, "Bộc lộ nỗi đau xót nghẹn ngào khi Bác Hồ qua đời."),
            RawQuestion("$tag Truyện ngắn 'Chiếc lược ngà' của Nguyễn Quang Sáng viết về tình cảm nào?", listOf("Tình phụ tử thiêng liêng trong chiến tranh", "Tình thầy trò", "Tình yêu thiên nhiên", "Tình hàng xóm"), 0, "Khắc họa tình cha con sâu nặng giữa ông Sáu và bé Thu."),
            RawQuestion("$tag Bài thơ 'Đồng chí' của Chính Hữu sáng tác vào thời kỳ nào?", listOf("Kháng chiến chống Pháp (1948)", "Kháng chiến chống Mỹ", "Thời bình sau 1975", "Phong trào Thơ mới 1932"), 0, "Sáng tác đầu năm 1948 sau chiến dịch Việt Bắc Thu - Đông 1947."),
            RawQuestion("$tag Nhân vật anh thanh niên trong 'Lặng lẽ Sa Pa' làm công việc gì?", listOf("Làm công tác khí tượng kiêm vật lí địa cầu", "Trồng rừng phòng hộ", "Dạy học vùng cao", "Kỹ sư cầu đường"), 0, "Anh sống một mình trên đỉnh Yên Sơn làm công tác khí tượng đo gió, mây, mưa."),
            RawQuestion("$tag Tác giả của 'Bình Ngô đại cáo' là ai?", listOf("Nguyễn Trãi", "Lý Thường Kiệt", "Trần Hưng Đạo", "Nguyễn Đình Chiểu"), 0, "Nguyễn Trãi thay lời Lê Lợi viết 'Bình Ngô đại cáo' năm 1428."),
